class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in GCMonitor.java in a real project ───
class GCMonitor {
    private static final Logger log = Logger.getLogger(GCMonitor.class.getName());

    // Separates Young (Minor) collectors from Old (Major/Full) collectors by name.
    void snapshot(String label) {
        for (var gc : java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            String kind = gc.getName().toLowerCase().contains("young")
                    || gc.getName().toLowerCase().contains("scavenge")
                    || gc.getName().toLowerCase().contains("copy") ? "MINOR" : "MAJOR/FULL";
            log.info(String.format("%-22s | %-10s collector=%-24s count=%d totalTime=%dms",
                    label, kind, gc.getName(), gc.getCollectionCount(), gc.getCollectionTime()));
        }
    }
}
